use std::{fs,collections::{HashMap,BTreeSet},hash::Hash,sync::Arc,path::Path};
use serde_json::{json,Value};use zopro_bn254::{Fr,G1Affine,G1Projective,G2Affine,G2Projective};
use zopro_prover::{Prover,zopro_core::{self,artifact::Artifact,verify::{compress_g1,compress_g2}}};
#[global_allocator]static ALLOCATOR:zopro_core::alloc::Allocator=zopro_core::alloc::Allocator;
#[derive(Default)]struct Counts<const N:usize>{map:HashMap<[u8;N],u8>,rows:usize,identities:usize}
impl<const N:usize>Counts<N>{
 fn add(&mut self,encoded:[u8;N],negative:[u8;N],identity:bool){self.rows+=1;if identity{self.identities+=1;assert_eq!(encoded,negative);return;}let mut expected=encoded;expected[0]^=0x40;assert_eq!(expected,negative);let mut key=encoded;let sign=if key[0]&0x40!=0{2}else{1};key[0]&=!0x40;*self.map.entry(key).or_default()|=sign;}
 fn stats(&self)->Value{let both=self.map.values().filter(|&&s|s==3).count();let exact=self.map.len()+both;let nonzero=self.rows-self.identities;assert!(exact<=nonzero);json!({"rows":self.rows,"identity_rows":self.identities,"nonidentity_rows":nonzero,"exact_point_classes":exact,"signed_point_classes":self.map.len(),"classes_with_both_signs":both,"exact_duplicate_removals":nonzero-exact,"signed_total_removals":nonzero-self.map.len(),"signed_removal_fraction_nonidentity":(nonzero-self.map.len())as f64/nonzero.max(1)as f64,"map_entries":self.map.len(),"map_capacity":self.map.capacity()})}
}
struct Reader<'a>{bytes:&'a[u8],at:usize}
impl<'a>Reader<'a>{fn take(&mut self,n:usize)->Result<&'a[u8],String>{let end=self.at.checked_add(n).ok_or("offset overflow")?;let s=self.bytes.get(self.at..end).ok_or("truncated range")?;self.at=end;Ok(s)}fn length(&mut self)->Result<usize,String>{usize::try_from(u64::from_le_bytes(self.take(8)?.try_into().unwrap())).map_err(|_|"length overflow".into())}fn align(&mut self)->Result<(),String>{let pad=(64-self.at%64)%64;if self.take(pad)?.iter().any(|&b|b!=0){return Err("nonzero padding".into());}Ok(())}}
fn ranges(raw:&[u8])->Result<Vec<(&'static str,&[u8])>,String>{if raw.get(..16)!=Some(b"zopro-euler-v2\0\0"as&[u8]){return Err("expected current Euler v2".into());}let mut r=Reader{bytes:raw,at:16};let n=r.length()?;let head=r.take(n)?;let(a,end)=Artifact::head(head).map_err(str::to_owned)?;if end!=head.len(){return Err("header tail".into());}r.align()?;let meta=r.take(128)?;if meta[80..].iter().any(|&b|b!=0){return Err("reserved metadata".into());}let slots=usize::try_from(u64::from_le_bytes(meta[..8].try_into().unwrap())).map_err(|_|"slot overflow")?;let public=usize::try_from(u64::from_le_bytes(meta[8..16].try_into().unwrap())).map_err(|_|"public overflow")?;let [na,nb,nk,nz,nb2]=a.points.map(|n|n as usize);let domain=nz.checked_add(1).ok_or("domain overflow")?;if !domain.is_power_of_two()||public!=a.public as usize||nb!=nb2{return Err("dimensions".into());}let mut out=Vec::new();for(label,n,size)in[("A_G1",na,64),("B1_unused_rerandomized",nb,64),("folded_private_G1",nk.checked_add(slots).ok_or("private overflow")?,64),("product_G1",domain,64),("B_G2",nb2,128),("public_correction_G1",public,64)]{let bytes=n.checked_mul(size).ok_or("point bytes overflow")?;let s=r.take(bytes)?;out.push((label,s));}r.take(slots.checked_mul(8).ok_or("slot bytes overflow")?)?;r.align()?;let n=r.length()?;r.take(n)?;if r.at!=raw.len(){return Err("trailing bytes".into());}Ok(out)}
fn g1(bytes:&[u8],counts:&mut Counts<32>){assert!(bytes.len().is_multiple_of(64));for tile in bytes.chunks(4096*64){for p in zopro_core::decode_g1(tile){assert!(p.is_on_curve());counts.add(compress_g1(&p),compress_g1(&-p),p.is_identity());}}}
fn g2(bytes:&[u8],counts:&mut Counts<64>){assert!(bytes.len().is_multiple_of(128));for tile in bytes.chunks(4096*128){for p in zopro_core::decode_g2(tile){assert!(p.is_on_curve());counts.add(compress_g2(&p),compress_g2(&-p),p.is_identity());}}}
fn run(cases:&Value){assert_eq!(cases.as_array().unwrap().len(),9);for c in cases.as_array().unwrap(){let file=fs::File::open(c["image"].as_str().unwrap()).unwrap();let mapping=unsafe{memmap2::Mmap::map(&file).unwrap()};let mapping=Arc::new(mapping);let prover=Prover::load_image(mapping.clone()).unwrap();drop(prover);let rs=ranges(&mapping).unwrap();let mut rows=Vec::new();for label in ["A_G1","B_G2","folded_private_G1","product_G1"]{let bytes=rs.iter().find(|(n,_)|*n==label).unwrap().1;let st=if label=="B_G2"{let mut counts=Counts::default();g2(bytes,&mut counts);counts.stats()}else{let mut counts=Counts::default();g1(bytes,&mut counts);counts.stats()};rows.push(json!({"query":label,"stats":st}));}let mut combined=Counts::default();for label in ["folded_private_G1","product_G1"]{g1(rs.iter().find(|(n,_)|*n==label).unwrap().1,&mut combined);}let separate:usize=rows.iter().filter(|r|["folded_private_G1","product_G1"].contains(&r["query"].as_str().unwrap())).map(|r|r["stats"]["signed_point_classes"].as_u64().unwrap()as usize).sum();let k=rs.iter().find(|(n,_)|*n=="folded_private_G1").unwrap().1.len()/64;let h=rs.iter().find(|(n,_)|*n=="product_G1").unwrap().1.len()/64;assert!(separate>=combined.map.len());rows.push(json!({"query":"combined_KH_G1","stats":combined.stats(),"extra_cross_query_signed_class_removals":separate-combined.map.len(),"fused_size_geometry":(1024..65536).contains(&k)&&(1024..65536).contains(&h)&&k+h<65536,"geometry_is_not_full_runtime_eligibility":true}));println!("ROW {}",json!({"shape":c["shape"],"image":c["image"],"queries":rows,"accepted_loader_validated":true}));}println!("COMPLETE nineimages45querycounts,noSDKproofs,noadoption");}
fn main(){let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),2);let cases:Value=serde_json::from_slice(&fs::read(Path::new(&args[1])).unwrap()).unwrap();run(&cases);}
#[cfg(test)]mod tests{use super::*;
 #[test]fn signed_counts_match_independent_sorted_sets(){let mut counts=Counts::default();let mut exact=BTreeSet::new();let mut signed=BTreeSet::new();for i in 0..511{let p=if i%19==0{G1Affine::IDENTITY}else{(G1Affine::GENERATOR*Fr::from((i%17+1)as u64)).to_affine()};let p=if i%3==0{-p}else{p};let e=compress_g1(&p);counts.add(e,compress_g1(&-p),p.is_identity());if !p.is_identity(){exact.insert(e);let mut n=e;n[0]&=!0x40;signed.insert(n);}}let s=counts.stats();assert_eq!(s["exact_point_classes"],exact.len());assert_eq!(s["signed_point_classes"],signed.len());assert_eq!(s["signed_point_classes"],17);}
 #[test]fn signed_scalar_combination_matches_g1_and_g2_generator_oracles(){let mut a=G1Projective::IDENTITY;let mut b=G2Projective::IDENTITY;let mut sum=Fr::ZERO;let mut groups=HashMap::<u64,Fr>::new();for i in 0..71{let w=(i%9+1)as u64;let s=Fr::from((i*7919+1)as u64);let sign=if i%3==0{-Fr::ONE}else{Fr::ONE};let c=s*sign;let p=(G1Affine::GENERATOR*Fr::from(w)).to_affine();let q=(G2Affine::GENERATOR*Fr::from(w)).to_affine();a+=(if i%3==0{-p}else{p})*s;b+=(if i%3==0{-q}else{q})*s;sum+=Fr::from(w)*c;*groups.entry(w).or_insert(Fr::ZERO)+=c;}let mut ar=G1Projective::IDENTITY;let mut br=G2Projective::IDENTITY;for(w,s)in groups{ar+=G1Affine::GENERATOR*(Fr::from(w)*s);br+=G2Affine::GENERATOR*(Fr::from(w)*s);}assert_eq!(a.to_affine(),ar.to_affine());assert_eq!(b.to_affine(),br.to_affine());assert_eq!(a.to_affine(),(G1Affine::GENERATOR*sum).to_affine());assert_eq!(b.to_affine(),(G2Affine::GENERATOR*sum).to_affine());}
 #[test]fn zero_only_counts_no_classes(){let mut c=Counts::default();for _ in 0..23{c.add(compress_g2(&G2Affine::IDENTITY),compress_g2(&G2Affine::IDENTITY),true);}assert_eq!(c.stats()["signed_point_classes"],0);assert_eq!(c.stats()["identity_rows"],23);}
 #[test]fn range_arithmetic_rejects_overflow_and_truncation(){let mut r=Reader{bytes:&[0;8],at:0};assert!(r.take(9).is_err());r.at=usize::MAX;assert!(r.take(2).is_err());assert!(ranges(&[0;16]).is_err());let mut r=Reader{bytes:&[1,2],at:1};assert!(r.align().is_err());}
}
